```yaml
name: Deployment Summary

on:
  pull_request:
    types: [closed]
    branches:
      - main
      - master

permissions:
  pull-requests: write
  contents: read

jobs:
  deployment-summary:
    if: github.event.pull_request.merged == true
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Generate Deployment Summary
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            const title = pr.title;
            const body = pr.body;
            const author = pr.user.login;
            const mergeCommit = pr.merge_commit_sha;

            // Extract Linear Ticket if present
            const linearMatch = body.match(/Fixes (NV-\d+)/);
            const linearTicket = linearMatch ? linearMatch[1] : 'N/A';

            // Extract changed files summary (simplified)
            const changedFiles = context.payload.pull_request.changed_files || 0;
            const additions = context.payload.pull_request.additions || 0;
            const deletions = context.payload.pull_request.deletions || 0;

            const summary = `
            # 🚀 Deployment Summary

            ## Pull Request Details
            - **Title**: ${title}
            - **Author**: @${author}
            - **Merge Commit**: [\`${mergeCommit.substring(0, 7)}\`](https://github.com/${context.repo.owner}/${context.repo.repo}/commit/${mergeCommit})
            - **Linear Ticket**: ${linearTicket}

            ## Changes Overview
            - **Files Changed**: ${changedFiles}
            - **Additions**: +${additions}
            - **Deletions**: -${deletions}

            ## Description
            ${body || 'No description provided.'}

            ---
            *Auto-generated by GitHub Actions*
            `;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: summary
            });

            console.log('Deployment summary comment created successfully.');
```

